import sys

sys.setrecursionlimit(1 << 20)


def dfs(u, fa, adj, siz):
    siz[u] = 1
    for v in adj[u]:
        if v != fa:
            dfs(v, u, adj, siz)
            siz[u] += siz[v]


def find_centroid(n, adj, siz, root=1):
    u, parent = root, -1
    while True:
        moved = False
        for v in adj[u]:
            if v != parent and siz[v] * 2 > n:
                parent, u = u, v
                moved = True
                break
        if not moved:
            return u


def main():
    n = 7
    edges = [(1, 2), (1, 3), (2, 4), (2, 5), (3, 6), (3, 7)]
    adj = [[] for _ in range(n + 1)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    siz = [0] * (n + 1)
    dfs(1, 0, adj, siz)
    c = find_centroid(n, adj, siz)
    # 校验：删去 c 后所有连通块 <= n/2
    seen = [False] * (n + 1)
    def count_block(start, ban):
        st = [start]
        seen[start] = True
        cnt = 0
        while st:
            u = st.pop()
            cnt += 1
            for v in adj[u]:
                if v != ban and not seen[v]:
                    seen[v] = True
                    st.append(v)
        return cnt
    blocks = []
    seen[c] = True
    for v in adj[c]:
        if not seen[v]:
            blocks.append(count_block(v, c))
    print("centroid =", c)
    print("block sizes after removal =", blocks)
    assert all(b * 2 <= n for b in blocks), "not a centroid!"
    print("OK")


if __name__ == "__main__":
    main()
